import Link from "next/link";
import "./globals.css";

export default function Home() {
  return (
    <main className="home">
      {/* HERO */}
      <section className="hero">
        <h1>EcoLoop</h1>
        <p className="tagline">
          Turning waste into value by connecting households, companies, and collectors.
        </p>

        <div className="cta">
          <Link href="/auth" className="btn primary">
            Get Started
          </Link>
          <Link href="/auth" className="btn secondary">
            Login
          </Link>
        </div>
      </section>

      {/* HOW IT WORKS */}
      <section className="how">
        <h2>How EcoLoop Works</h2>

        <div className="steps">
          <div className="step">
            <h3>🏠 Households</h3>
            <p>
              Log your waste, track environmental impact, and schedule pickups
              directly from your dashboard.
            </p>
          </div>

          <div className="step">
            <h3>🏭 Companies</h3>
            <p>
              Post industrial by-product waste and get matched with households
              or recyclers who can reuse it.
            </p>
          </div>

          <div className="step">
            <h3>🚚 Collectors</h3>
            <p>
              Accept pickup jobs, manage routes, and earn by closing the waste loop.
            </p>
          </div>
        </div>
      </section>

      {/* VALUE PROPOSITION */}
      <section className="value">
        <h2>Why EcoLoop?</h2>

        <ul>
          <li>♻️ Reduce waste going to landfills</li>
          <li>📊 Track CO₂ savings transparently</li>
          <li>🤝 Connect waste producers to waste users</li>
          <li>💼 Create green economic opportunities</li>
        </ul>
      </section>

      {/* FINAL CTA */}
      <section className="final">
        <h2>Start closing the loop today</h2>
        <Link href="/auth" className="btn primary large">
          Create an Account
        </Link>
      </section>
    </main>
  );
}
